3: /* Touch-first layout: keep the play surface clear and controls inside device safe areas. */
4: @media (pointer:coarse) and (hover:none){.controls-hint{display:none}.touch-controls{display:flex}}
5: .touch-controls{bottom:calc(18px + env(safe-area-inset-bottom));padding-left:max(17px,env(safe-area-inset-left));padding-right:max(17px,env(safe-area-inset-right))}
6: .joystick,.jump-touch{touch-action:none;-webkit-tap-highlight-color:transparent}
7: .jump-touch{transition:transform .12s,background .12s}
8: .jump-touch:active{transform:scale(.94);background:#77efdb66}
9: @media(max-width:540px){.session-card{top:auto;bottom:calc(164px + env(safe-area-inset-bottom));right:12px;width:158px}.right-rail{display:none}}
10: @media(max-width:540px) and (max-height:570px){.session-card{top:80px;bottom:auto}}
